'use strict';

const Database = require('better-sqlite3');

/**
 * Creates the events + outbox schema on a better-sqlite3 database.
 */
function migrate(db) {
  db.exec(`
    CREATE TABLE IF NOT EXISTS events (
      id         INTEGER PRIMARY KEY AUTOINCREMENT,
      type       TEXT NOT NULL,
      payload    TEXT NOT NULL,
      created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
    );

    CREATE TABLE IF NOT EXISTS outbox (
      id            INTEGER PRIMARY KEY AUTOINCREMENT,
      event_id      INTEGER NOT NULL REFERENCES events(id),
      status        TEXT NOT NULL DEFAULT 'pending'
                    CHECK (status IN ('pending','delivered','failed')),
      attempt_count INTEGER NOT NULL DEFAULT 0,
      last_error    TEXT,
      created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
      updated_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
    );

    CREATE INDEX IF NOT EXISTS idx_outbox_status ON outbox(status, id);
  `);
}

/**
 * Records an event and its corresponding outbox row atomically.
 * Either both rows exist afterwards, or neither does.
 */
function makeRecordEvent(db) {
  const insertEvent = db.prepare(
    'INSERT INTO events (type, payload) VALUES (?, ?)'
  );
  const insertOutbox = db.prepare(
    "INSERT INTO outbox (event_id) VALUES (?)"
  );

  return db.transaction((type, payload) => {
    const body = typeof payload === 'string' ? payload : JSON.stringify(payload);
    const { lastInsertRowid: eventId } = insertEvent.run(type, body);
    const { lastInsertRowid: outboxId } = insertOutbox.run(eventId);
    return { eventId: Number(eventId), outboxId: Number(outboxId) };
  });
}

function openDb(path) {
  const db = new Database(path);
  db.pragma('journal_mode = WAL');
  db.pragma('foreign_keys = ON');
  migrate(db);
  return db;
}

module.exports = { openDb, migrate, makeRecordEvent };

