'use strict';

/**
 * Outbox dispatcher: polls for pending outbox rows and POSTs each event
 * to the configured target URL with exponential backoff.
 *
 * All timing is injectable so tests can shrink delays:
 *   - delays:     backoff schedule between attempts (default 1s, 2s, 4s)
 *   - maxTries:   attempt budget before a row is marked 'failed' (default 3)
 *   - sleep:      async delay implementation
 *   - fetchImpl:  HTTP client (defaults to global fetch)
 *
 * Backoff note: with maxTries=3 there are at most 2 gaps between attempts,
 * so delays[0]=1s and delays[1]=2s are the effective 1s -> 2s ladder;
 * delays[2] would be used if maxTries were raised to 4.
 */
const DEFAULT_DELAYS_MS = [1000, 2000, 4000];
const DEFAULT_MAX_TRIES = 3;

class Dispatcher {
  constructor({
    db,
    targetUrl,
    delays = DEFAULT_DELAYS_MS,
    maxTries = DEFAULT_MAX_TRIES,
    pollDelayMs = 50,
    sleep = realSleep,
    fetchImpl = (...args) => fetch(...args),
    logger = () => {},
  }) {
    if (!db) throw new Error('db is required');
    if (!targetUrl) throw new Error('targetUrl is required');
    this.db = db;
    this.targetUrl = targetUrl;
    this.delays = delays;
    this.maxTries = maxTries;
    this.pollDelayMs = pollDelayMs;
    this.sleep = sleep;
    this.fetchImpl = fetchImpl;
    this.log = logger;
    this.stopped = false;

    this.statements = {
      pending: db.prepare(
        `SELECT o.id AS outbox_id, o.attempt_count, e.type, e.payload
           FROM outbox o JOIN events e ON e.id = o.event_id
          WHERE o.status = 'pending'
          ORDER BY o.id`
      ),
      markDelivered: db.prepare(
        `UPDATE outbox
            SET status = 'delivered', attempt_count = ?, last_error = NULL,
                updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now')
          WHERE id = ?`
      ),
      markFailed: db.prepare(
        `UPDATE outbox
            SET status = 'failed', attempt_count = ?, last_error = ?,
                updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now')
          WHERE id = ?`
      ),
      bumpAttempt: db.prepare(
        `UPDATE outbox
            SET attempt_count = ?, last_error = ?,
                updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now')
          WHERE id = ? AND status = 'pending'`
      ),
    };

    // Each row is retried independently; wrap per-row updates so a crash
    // mid-dispatch never loses the attempt bookkeeping.
    this.processRow = db.transaction((row) => this._processRowTx(row));
  }

  stop() {
    this.stopped = true;
  }

  /** Long-running loop until stop() is called. Resolves when drained+stopped. */
  async run() {
    while (!this.stopped) {
      const worked = await this.tick();
      if (!worked && !this.stopped) {
        await this.sleep(this.pollDelayMs);
      }
    }
  }

  /** One sweep over pending rows. Returns true if any row was processed. */
  async tick() {
    const rows = this.statements.pending.all();
    let worked = false;
    for (const row of rows) {
      if (this.stopped) break;
      await this.processRow(row);
      worked = true;
    }
    return worked || rows.length > 0;
  }

  _processRowTx(row) {
    const attemptNo = row.attempt_count + 1; // 1-based attempt number
    try {
      this._deliverSync(row); // replaced below; see deliver()
    } catch (err) {
      if (attemptNo >= this.maxTries) {
        this.statements.markFailed.run(attemptNo, String(err.message), row.outbox_id);
        this.log(`outbox #${row.outbox_id} failed after ${attemptNo} attempts: ${err.message}`);
        return { outcome: 'failed', attemptNo };
      }
      this.statements.bumpAttempt.run(attemptNo, String(err.message), row.outbox_id);
      this.log(`outbox #${row.outbox_id} attempt ${attemptNo} failed: ${err.message}`);
      return { outcome: 'retry', attemptNo };
    }
  }
}

// HTTP + backoff are async, so the transactional wrapper above can't hold the
// SQLite transaction open across network I/O. Instead: perform delivery first
// (pure network), then apply the resulting state change in a tiny transaction.
Object.assign(Dispatcher.prototype, {
  async deliver(row) {
    const attemptNo = row.attempt_count + 1;

    let error = null;
    try {
      const res = await this.fetchImpl(this.targetUrl, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: row.payload,
        signal: AbortSignal.timeout ? AbortSignal.timeout(5000) : undefined,
      });
      if (!res.ok) {
        error = new Error(`target responded ${res.status}`);
      }
    } catch (err) {
      error = err;
    }

    return this.db.transaction(() => {
      if (!error) {
        this.statements.markDelivered.run(attemptNo, row.outbox_id);
        this.log(`outbox #${row.outbox_id} delivered on attempt ${attemptNo}`);
        return { outcome: 'delivered', attemptNo };
      }
      if (attemptNo >= this.maxTries) {
        this.statements.markFailed.run(attemptNo, error.message, row.outbox_id);
        this.log(`outbox #${row.outbox_id} failed after ${attemptNo} attempts: ${error.message}`);
        return { outcome: 'failed', attemptNo };
      }
      this.statements.bumpAttempt.run(attemptNo, error.message, row.outbox_id);
      const backoff = this.delays[Math.min(attemptNo - 1, this.delays.length - 1)] ?? 0;
      this.log(`outbox #${row.outbox_id} attempt ${attemptNo} failed (${error.message}); backing off ${backoff}ms`);
      return { outcome: 'retry', attemptNo, backoff };
    })();
  },

  /** Deliver one row through its full retry ladder. Returns final outcome. */
  async processWithRetries(row) {
    let current = row;
    /* eslint-disable no-constant-condition */
    while (true) {
      const result = await this.deliver(current);
      if (result.outcome !== 'retry') return result.outcome;
      await this.sleep(result.backoff ?? 0);
      current = this.db
        .prepare('SELECT id AS outbox_id, attempt_count FROM outbox WHERE id = ?')
        .get(row.outbox_id);
    }
  },
});

function realSleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/** Convenience: drain every pending row (with retries) to a terminal state. */
async function drain(db, dispatcher) {
  let row;
  const selectNext = db.prepare(
    `SELECT o.id AS outbox_id, o.attempt_count, e.type, e.payload
       FROM outbox o JOIN events e ON e.id = o.event_id
      WHERE o.status = 'pending'
      ORDER BY o.id
      LIMIT 1`
  );
  while ((row = selectNext.get())) {
    await dispatcher.processWithRetries(row);
  }
}

module.exports = { Dispatcher, drain, DEFAULT_DELAYS_MS, DEFAULT_MAX_TRIES };

