'use strict';

const express = require('express');
const { makeRecordEvent } = require('./outbox');

/**
 * Builds the ingest service. POST /events records an event plus its outbox
 * row in a single better-sqlite3 transaction.
 */
function createApp(db) {
  const recordEvent = makeRecordEvent(db);
  const app = express();
  app.use(express.json({ type: '*/*' }));

  app.post('/events', (req, res) => {
    const type = req.get('x-event-type') || (req.body && req.body.type) || 'unknown';
    try {
      const { eventId, outboxId } = recordEvent(type, req.body ?? {});
      res.status(202).json({ eventId, outboxId, status: 'queued' });
    } catch (err) {
      res.status(500).json({ error: err.message });
    }
  });

  return app;
}

module.exports = { createApp };

